package com.afterfall.action;

import com.afterfall.domain.SurvivorId;
import java.util.Objects;

/**
 * An immutable proposal for a simulation event generated by an action evaluation.
 * Does not carry premature global event sequence numbers, which are assigned by TickCoordinator in M4.
 */
public record ProposedEvent(
        String eventType,
        SurvivorId survivorId,
        String summary,
        int severity
) {
    public ProposedEvent {
        Objects.requireNonNull(eventType, "eventType");
        Objects.requireNonNull(survivorId, "survivorId");
        Objects.requireNonNull(summary, "summary");
    }
}
